import openpyxl
from openpyxl.utils import get_column_letter

path='/root/data/workbook.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)
ws_task=wb['Task']
ws_data=wb['Data']

# Task sheet inspections
print('\n[Task] Years in row 10, cols H-L:')
for col in range(8, 13):
    cell=ws_task.cell(row=10, column=col)
    print(f"{get_column_letter(col)}10 = {cell.value!r}")

blocks=[(12,17),(19,24),(26,31)]
print('\n[Task] Series codes in column D:')
for start,end in blocks:
    print(f"Rows {start}-{end}:")
    for r in range(start,end+1):
        v=ws_task[f'D{r}'].value
        print(f"  D{r} = {v!r}")

# Check what's in yellow cells (assume the blocks H-L rows 12-17,19-24,26-31, and other blocks)
print('\n[Task] Existing values in yellow blocks (should be empty/placeholders):')
areas=[('H12:L17',12,17,8,12),('H19:L24',19,24,8,12),('H26:L31',26,31,8,12),('H35:L40',35,40,8,12),('H42:L47',42,47,8,12),('H50:L50',50,50,8,12)]
for label, r1,r2,c1,c2 in areas:
    nonempty=[]
    for r in range(r1,r2+1):
        for c in range(c1,c2+1):
            addr=f"{get_column_letter(c)}{r}"
            val=ws_task.cell(row=r,column=c).value
            if val not in (None,''):
                nonempty.append((addr,val))
    print(f" {label}: {len(nonempty)} non-empty")
    for addr,val in nonempty[:20]:
        print(f"   {addr} = {val!r}")
    if len(nonempty)>20:
        print('   ...')

# Data sheet layout inspection
print('\n[Data] Inspect rows 20-38, cols A-Z (values):')
for r in range(20,39):
    row=[]
    for c in range(1,27):
        v=ws_data.cell(row=r,column=c).value
        row.append(v)
    non=[(get_column_letter(i+1),v) for i,v in enumerate(row) if v not in (None,'')]
    if non:
        preview=', '.join([f"{col}{r}={val!r}" for col,val in non[:12]])
        if len(non)>12:
            preview += f" ... (+{len(non)-12} more)"
        print(f" Row {r}: {preview}")

# Identify likely series code column by checking rows 21-38 for strings matching Task series codes
codes=[]
for start,end in blocks:
    for r in range(start,end+1):
        codes.append(ws_task[f'D{r}'].value)
code_set=set([c for c in codes if c is not None])

print('\n[Data] Check which columns contain Task series codes (rows 21-38):')
for c in range(1,27):
    hits=[]
    for r in range(21,39):
        v=ws_data.cell(row=r,column=c).value
        if v in code_set:
            hits.append((r,v))
    if hits:
        col=get_column_letter(c)
        print(f" Column {col}: {len(hits)} hits; e.g. {hits[:5]}")

# Identify year header row and columns by scanning row 18-22 for year values matching Task years
years=[ws_task.cell(row=10,column=c).value for c in range(8,13)]
year_set=set(years)
print('\n[Data] Check where year headers are (rows 18-22):')
for r in range(18,23):
    hits=[]
    for c in range(1,27):
        v=ws_data.cell(row=r,column=c).value
        if v in year_set:
            hits.append((get_column_letter(c),v))
    if hits:
        print(f" Row {r} has year matches: {hits}")

# Labels in Task rows 35-40 and 42-47 and row 50
print('\n[Task] Region labels rows 35-40 (cols B-G):')
for r in range(35,41):
    vals={col: ws_task[f"{col}{r}"].value for col in ['B','C','D','E','F','G']}
    shown=[f"{k}={v!r}" for k,v in vals.items() if v not in (None,'')]
    print(f" Row {r}: "+(', '.join(shown) if shown else '(all empty)'))

print('\n[Task] Statistics labels rows 42-47 (cols B-G):')
for r in range(42,48):
    vals={col: ws_task[f"{col}{r}"].value for col in ['B','C','D','E','F','G']}
    shown=[f"{k}={v!r}" for k,v in vals.items() if v not in (None,'')]
    print(f" Row {r}: "+(', '.join(shown) if shown else '(all empty)'))

print('\n[Task] GCM label row 50 (cols B-G):')
vals={col: ws_task[f"{col}50"].value for col in ['B','C','D','E','F','G']}
shown=[f"{k}={v!r}" for k,v in vals.items() if v not in (None,'')]
print(', '.join(shown) if shown else '(all empty)')

